from __future__ import annotations
import base64
import gzip
import hashlib
import json

VERSION = "39.0"
EXPECTED_SHA256 = "4a90ede71c03d8fc496adba06dbc8917fefdaa2be62db01a1be72f40575e4271"
_DATA_B64 = """"""

def load_data():
    packed = base64.b64decode("".join(_DATA_B64.split()))
    if hashlib.sha256(packed).hexdigest() != EXPECTED_SHA256:
        raise RuntimeError("Writing V39 source payload checksum mismatch.")
    data = json.loads(gzip.decompress(packed).decode("utf-8"))
    canonical = data.get("canonical_sets") or []
    extra = data.get("extra_part2") or []
    if len(canonical) != 50:
        raise RuntimeError(f"Expected 50 canonical Writing Sets; found {len(canonical)}")
    if sum(len(row.get("parts") or {}) for row in canonical) != 100:
        raise RuntimeError("Expected exactly 100 canonical Writing tasks.")
    if len(extra) != 10:
        raise RuntimeError(f"Expected 10 supplementary Part 2 tasks; found {len(extra)}")
    return data
